#import "PDFReaderViewController.h"
#import "PDFPageView.h"
#import "BookmarkStore.h"
#import "AppearanceStore.h"
#import "AnnotationOverlayView.h"
#import "AnnotationStore.h"
#import "SearchViewController.h"
#import "OutlineViewController.h"
#import "PDFOutlineParser.h"
@implementation PDFReaderViewController
- (id)initWithPDFPath:(NSString*)p{if((self=[super initWithNibName:nil bundle:nil]))_pdfPath=[p copy];return self;}
- (void)viewDidLoad{[super viewDidLoad];self.view.backgroundColor=[UIColor darkGrayColor];self.title=[[_pdfPath lastPathComponent]stringByDeletingPathExtension];_document=CGPDFDocumentCreateWithURL((CFURLRef)[NSURL fileURLWithPath:_pdfPath]);if(!_document){UIAlertView*e=[[[UIAlertView alloc]initWithTitle:@"PDF açılamadı" message:@"Dosya bozuk veya desteklenmiyor." delegate:nil cancelButtonTitle:@"Tamam" otherButtonTitles:nil]autorelease];[e show];return;}_pageCount=CGPDFDocumentGetNumberOfPages(_document);_currentPage=[BookmarkStore lastPageForPath:_pdfPath];if(_currentPage<1||_currentPage>_pageCount)_currentPage=1;_scrollView=[[UIScrollView alloc]initWithFrame:CGRectZero];_scrollView.delegate=self;_scrollView.minimumZoomScale=1;_scrollView.maximumZoomScale=5;_scrollView.bouncesZoom=YES;[self.view addSubview:_scrollView];_pageView=[[PDFPageView alloc]initWithFrame:CGRectZero];_pageView.theme=[AppearanceStore theme];[_scrollView addSubview:_pageView];_overlay=[[AnnotationOverlayView alloc]initWithFrame:CGRectZero];_overlay.pdfPath=_pdfPath;[_pageView addSubview:_overlay];UISwipeGestureRecognizer*l=[[[UISwipeGestureRecognizer alloc]initWithTarget:self action:@selector(swiped:)]autorelease];l.direction=UISwipeGestureRecognizerDirectionLeft;[_scrollView addGestureRecognizer:l];UISwipeGestureRecognizer*r=[[[UISwipeGestureRecognizer alloc]initWithTarget:self action:@selector(swiped:)]autorelease];r.direction=UISwipeGestureRecognizerDirectionRight;[_scrollView addGestureRecognizer:r];UITapGestureRecognizer*t=[[[UITapGestureRecognizer alloc]initWithTarget:self action:@selector(toggleChrome)]autorelease];[_scrollView addGestureRecognizer:t];_toolbar=[[UIToolbar alloc]initWithFrame:CGRectZero];_previousButton=[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemRewind target:self action:@selector(previousPage)];_nextButton=[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemFastForward target:self action:@selector(nextPage)];_bookmarkButton=[[UIBarButtonItem alloc]initWithTitle:@"☆" style:UIBarButtonItemStylePlain target:self action:@selector(toggleBookmark)];UIBarButtonItem*thumb=[[[UIBarButtonItem alloc]initWithTitle:@"Sayfalar" style:UIBarButtonItemStylePlain target:self action:@selector(showThumbs)]autorelease];UIBarButtonItem*more=[[[UIBarButtonItem alloc]initWithTitle:@"Daha Fazla" style:UIBarButtonItemStylePlain target:self action:@selector(showMore)]autorelease];_pageLabel=[[UILabel alloc]initWithFrame:CGRectMake(0,0,105,30)];_pageLabel.backgroundColor=[UIColor clearColor];_pageLabel.textAlignment=NSTextAlignmentCenter;_pageLabel.font=[UIFont boldSystemFontOfSize:14];UIBarButtonItem*pi=[[[UIBarButtonItem alloc]initWithCustomView:_pageLabel]autorelease];UIBarButtonItem*f=[[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemFlexibleSpace target:nil action:nil]autorelease];_toolbar.items=[NSArray arrayWithObjects:_previousButton,f,pi,_nextButton,_bookmarkButton,thumb,more,nil];[self.view addSubview:_toolbar];[self displayCurrentPage];}
- (void)viewDidLayoutSubviews{[super viewDidLayoutSubviews];CGFloat h=44;CGRect b=self.view.bounds;_toolbar.frame=CGRectMake(0,b.size.height-h,b.size.width,h);_scrollView.frame=CGRectMake(0,0,b.size.width,b.size.height-(_chromeHidden?0:h));[self layoutPage:NO];}
- (void)layoutPage:(BOOL)reset{if(!_document||!_pageCount)return;CGPDFPageRef p=CGPDFDocumentGetPage(_document,_currentPage);CGRect box=CGPDFPageGetBoxRect(p,kCGPDFMediaBox);CGFloat w=box.size.width,h=box.size.height;int rr=CGPDFPageGetRotationAngle(p);if(rr==90||rr==270){CGFloat q=w;w=h;h=q;}CGFloat aw=_scrollView.bounds.size.width-20,ah=_scrollView.bounds.size.height-20,s=MIN(aw/w,ah/h);CGSize z=CGSizeMake(floor(w*s),floor(h*s));CGFloat x=MAX(10,floor((_scrollView.bounds.size.width-z.width)/2)),y=MAX(10,floor((_scrollView.bounds.size.height-z.height)/2));_pageView.frame=CGRectMake(x,y,z.width,z.height);_overlay.frame=_pageView.bounds;if(reset)_scrollView.zoomScale=1;}
- (void)displayCurrentPage{CGPDFPageRef p=CGPDFDocumentGetPage(_document,_currentPage);[_pageView setPDFPage:p];_pageView.theme=[AppearanceStore theme];[BookmarkStore setLastPage:_currentPage forPath:_pdfPath];_overlay.page=_currentPage;[_overlay reloadAnnotations];_pageLabel.text=[NSString stringWithFormat:@"%lu / %lu",(unsigned long)_currentPage,(unsigned long)_pageCount];_previousButton.enabled=_currentPage>1;_nextButton.enabled=_currentPage<_pageCount;_bookmarkButton.title=[BookmarkStore isBookmarkedPage:_currentPage forPath:_pdfPath]?@"★":@"☆";[self layoutPage:YES];}
- (void)previousPage{if(_currentPage>1){_currentPage--;[self displayCurrentPage];}}
- (void)nextPage{if(_currentPage<_pageCount){_currentPage++;[self displayCurrentPage];}}
- (void)swiped:(UISwipeGestureRecognizer*)g{if(_scrollView.zoomScale>1.05)return;if(g.direction==UISwipeGestureRecognizerDirectionLeft)[self nextPage];else[self previousPage];}
- (void)toggleChrome{_chromeHidden=!_chromeHidden;self.navigationController.navigationBarHidden=_chromeHidden;_toolbar.hidden=_chromeHidden;[self.view setNeedsLayout];}
- (void)toggleBookmark{[BookmarkStore toggleBookmarkForPage:_currentPage forPath:_pdfPath];_bookmarkButton.title=[BookmarkStore isBookmarkedPage:_currentPage forPath:_pdfPath]?@"★":@"☆";}
- (void)showThumbs{ThumbnailViewController*v=[[[ThumbnailViewController alloc]initWithPDFPath:_pdfPath]autorelease];v.delegate=self;[self.navigationController pushViewController:v animated:YES];}
- (void)thumbnailControllerSelectedPage:(NSUInteger)p{_currentPage=p;[self displayCurrentPage];}
- (void)showMore{UIActionSheet*s=[[[UIActionSheet alloc]initWithTitle:@"Araçlar" delegate:self cancelButtonTitle:@"İptal" destructiveButtonTitle:nil otherButtonTitles:@"Sayfaya Git",@"Tema",@"Ara",@"İçindekiler",@"Çizim Aç/Kapat",@"Highlight",@"Not Ekle",@"İmza Ekle",@"Bu Sayfanın Notlarını Sil",nil]autorelease];[s showFromToolbar:_toolbar];}
- (void)actionSheet:(UIActionSheet*)s clickedButtonAtIndex:(NSInteger)b{if(s.tag==20)return;if(b==0){UIAlertView*a=[[[UIAlertView alloc]initWithTitle:@"Sayfaya Git" message:nil delegate:self cancelButtonTitle:@"İptal" otherButtonTitles:@"Git",nil]autorelease];a.alertViewStyle=UIAlertViewStylePlainTextInput;[a textFieldAtIndex:0].keyboardType=UIKeyboardTypeNumberPad;a.tag=10;[a show];}else if(b==1){UIActionSheet*t=[[[UIActionSheet alloc]initWithTitle:@"Tema" delegate:self cancelButtonTitle:@"İptal" destructiveButtonTitle:nil otherButtonTitles:@"Normal",@"Sepia",@"Gece",nil]autorelease];t.tag=20;[t showFromToolbar:_toolbar];}else if(b==2){[self.navigationController pushViewController:[[[SearchViewController alloc]initWithPDFPath:_pdfPath]autorelease] animated:YES];}else if(b==3){[self.navigationController pushViewController:[[[OutlineViewController alloc]initWithItems:[PDFOutlineParser outlineForDocument:_document]]autorelease] animated:YES];}else if(b==4){_overlay.drawingEnabled=!_overlay.drawingEnabled;}else if(b==5){[AnnotationStore addAnnotation:[NSDictionary dictionaryWithObjectsAndKeys:@"highlight",@"type",NSStringFromCGRect(CGRectMake(.15,.35,.70,.10)),@"rect",nil] path:_pdfPath page:_currentPage];[_overlay reloadAnnotations];}else if(b==6){[AnnotationStore addAnnotation:[NSDictionary dictionaryWithObjectsAndKeys:@"note",@"type",NSStringFromCGRect(CGRectMake(.05,.05,.04,.04)),@"rect",nil] path:_pdfPath page:_currentPage];[_overlay reloadAnnotations];}else if(b==7){UIAlertView*a=[[[UIAlertView alloc]initWithTitle:@"İmza" message:@"Adınızı/imzanızı yazın" delegate:self cancelButtonTitle:@"İptal" otherButtonTitles:@"Ekle",nil]autorelease];a.alertViewStyle=UIAlertViewStylePlainTextInput;a.tag=30;[a show];}else if(b==8){[AnnotationStore clearAnnotationsForPath:_pdfPath page:_currentPage];[_overlay reloadAnnotations];}}
- (void)actionSheet:(UIActionSheet*)s didDismissWithButtonIndex:(NSInteger)b{if(s.tag==20&&b>=0&&b<=2){[AppearanceStore setTheme:(PDFTheme)b];_pageView.theme=(PDFTheme)b;}}
- (void)alertView:(UIAlertView*)a clickedButtonAtIndex:(NSInteger)b{if(a.tag==10&&b==1){NSInteger p=[[[a textFieldAtIndex:0]text]integerValue];if(p>=1&&p<=(NSInteger)_pageCount){_currentPage=p;[self displayCurrentPage];}}else if(a.tag==30&&b==1){NSString*txt=[[a textFieldAtIndex:0]text];[AnnotationStore addAnnotation:[NSDictionary dictionaryWithObjectsAndKeys:@"signature",@"type",txt?txt:@"",@"text",NSStringFromCGRect(CGRectMake(.55,.80,.35,.10)),@"rect",nil] path:_pdfPath page:_currentPage];[_overlay reloadAnnotations];}}
- (UIView*)viewForZoomingInScrollView:(UIScrollView*)s{return _pageView;}
- (void)dealloc{_scrollView.delegate=nil;[_pdfPath release];[_scrollView release];[_pageView release];[_overlay release];[_toolbar release];[_pageLabel release];[_previousButton release];[_nextButton release];[_bookmarkButton release];if(_document)CGPDFDocumentRelease(_document);[super dealloc];}
@end
